import{readFile,mkdir,writeFile}from'node:fs/promises';import{netCents}from'./money.mjs';const orders=JSON.parse(await readFile('orders.json'));await mkdir('output',{recursive:true});for(const o of orders){const net=netCents(o.subtotalCents,o.discountPercent);await writeFile('output/'+o.id+'.json',JSON.stringify({...o,netCents:net},null,2));await writeFile('output/'+o.id+'.html',`<!doctype html><html><body><h1>Juniper ${o.id} order</h1><p>Fictional local preview</p><p>Net cents: <strong id="net">${net}</strong></p><button onclick="document.querySelector('#status').textContent='Reviewed'">Mark reviewed</button><p id="status">Pending</p></body></html>`);}console.log('Rendered '+orders.length+' local previews');
